BEGIN;
CREATE SCHEMA IF NOT EXISTS ged;
CREATE TABLE IF NOT EXISTS ged.cluster_node(id bigserial PRIMARY KEY,cluster_id text NOT NULL,node_id text NOT NULL,node_name text NOT NULL,color text NOT NULL,region text NOT NULL,availability_zone text NOT NULL,application_version text NOT NULL,commit_sha text NOT NULL,status text NOT NULL CHECK(status IN('STARTING','WARMING','READY','DRAINING','DRAINED','UNHEALTHY','STOPPING','OFFLINE')),started_at_utc timestamptz NOT NULL,last_heartbeat_at_utc timestamptz NOT NULL,drain_started_at_utc timestamptz,drained_at_utc timestamptz,registered_at_utc timestamptz NOT NULL DEFAULT now(),metadata_json jsonb NOT NULL DEFAULT '{}',UNIQUE(cluster_id,node_id));
CREATE INDEX IF NOT EXISTS ix_cluster_node_cluster ON ged.cluster_node(cluster_id); CREATE INDEX IF NOT EXISTS ix_cluster_node_color_status ON ged.cluster_node(cluster_id,color,status); CREATE INDEX IF NOT EXISTS ix_cluster_node_heartbeat ON ged.cluster_node(last_heartbeat_at_utc);
CREATE TABLE IF NOT EXISTS ged.cluster_node_heartbeat(id bigserial PRIMARY KEY,cluster_id text NOT NULL,node_id text NOT NULL,status text NOT NULL,heartbeat_at_utc timestamptz NOT NULL,health_json jsonb NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS ix_cluster_heartbeat_node_time ON ged.cluster_node_heartbeat(cluster_id,node_id,heartbeat_at_utc DESC);
CREATE TABLE IF NOT EXISTS ged.cluster_deployment(deployment_id uuid PRIMARY KEY,cluster_id text NOT NULL,release_id text NOT NULL,source_color text,target_color text NOT NULL,application_version text NOT NULL,commit_sha text NOT NULL,status text NOT NULL,requested_by text NOT NULL,started_at_utc timestamptz NOT NULL,finished_at_utc timestamptz,traffic_switched_at_utc timestamptz,rollback_started_at_utc timestamptz,rollback_finished_at_utc timestamptz,failure_code text,correlation_id uuid NOT NULL,manifest_json jsonb NOT NULL,summary_json jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS ged.cluster_deployment_node(deployment_id uuid NOT NULL REFERENCES ged.cluster_deployment,node_id text NOT NULL,color text NOT NULL,status text NOT NULL,release_path text,started_at_utc timestamptz,ready_at_utc timestamptz,drained_at_utc timestamptz,finished_at_utc timestamptz,health_json jsonb NOT NULL DEFAULT '{}',failure_code text,PRIMARY KEY(deployment_id,node_id));
CREATE TABLE IF NOT EXISTS ged.cluster_deployment_event(id bigserial PRIMARY KEY,deployment_id uuid NOT NULL REFERENCES ged.cluster_deployment,event_type text NOT NULL,occurred_at_utc timestamptz NOT NULL DEFAULT now(),node_id text,correlation_id uuid NOT NULL,payload_json jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS ged.cluster_traffic_state(cluster_id text PRIMARY KEY,active_color text NOT NULL,updated_at_utc timestamptz NOT NULL,confirmed_by_provider boolean NOT NULL DEFAULT false,deployment_id uuid);
CREATE TABLE IF NOT EXISTS ged.cluster_leader_lease(lease_name text NOT NULL,cluster_id text NOT NULL,owner_node_id text NOT NULL,acquired_at_utc timestamptz NOT NULL,renewed_at_utc timestamptz NOT NULL,expires_at_utc timestamptz NOT NULL,fencing_token bigint NOT NULL,metadata_json jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(lease_name,cluster_id));
COMMIT;
